import{_ as l,l as o,o as t,c as n,v as e,p as c,x as i,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"价格栅格","description":"","frontmatter":{"title":"价格栅格","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/price-grid-tick.md","filePath":"quant/price-grid-tick.md","lastUpdated":1789023840000}'),h={name:"quant/price-grid-tick.md"};function m(k,a,B,E,u,_){const r=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="价格栅格" tabindex="-1">价格栅格 <a class="header-anchor" href="#价格栅格" aria-label="Permalink to &quot;价格栅格&quot;">​</a></h1><div class="epigraph"><p>可提交的订单落在价格 tick 与数量手数张成的格子上。中点、亚 tick 改善和零售内化，是在这张公开格子内部另开的匹配层。</p><footer>—— 据 Harris 对离散价格与订单尺寸的讨论；对照 Hasbrouck 对微观价格与中点的经验处理</footer></div><p><a href="/quant/tick-size-regime">tick 制度</a>给了价格步长，<a href="/quant/lot-size-odd-lot">手数与零股</a>给了数量步长。本课把两维收成<strong>价格栅格</strong>：公开限价单的合法坐标是 \\((n\\Delta, k\\cdot\\mathrm{lot})\\)，再问中点单、亚 tick、peg 指令如何寄生在格子内部。Hasbrouck 把微观价格写成买卖报价的加权，那是连续化的描述；提交时引擎仍只接受格子上的点。缺口是：研究里的中点 \\(m\\) 往往不在格子上，交易里的限价必须在格子上，两者混用会让「挂在中点」变成一句无法执行的话。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开 BBO 是格子上的两个点 \\(b=n_b\\Delta\\)、\\(a=n_a\\Delta\\)，中点 \\(m=(a+b)/2\\) 在 \\(a-b\\) 为奇数 tick 时<strong>落在半个 tick 上</strong>，公开限价不能挂在那里。要在中点成交，必须换协议：中点撮合的暗池、peg-to-mid 指令、或零售批发商的价格改善。先修课已经说明 \\(n=1\\) 时价差被钉住；本课补充：被钉住时，经济上想提供的改善无法写成公开限价，只能离开展示簿。于是出现两层价格：格子上的展示层，格子内的匹配层。</p><p>数量维同样。想买「半手再加 1 股」可能根本不能作为一张公开限价存在。算法输出的连续仓位必须投影到栅格上，投影误差是换手和跟踪误差的来源，不是微观结构噪声。问题是声明：哪些分析用连续中点，哪些下单用格子点，格子内成交如何对照。</p><h3 id="奇数-tick-价差与半-tick-中点" tabindex="-1">奇数 tick 价差与半 tick 中点 <a class="header-anchor" href="#奇数-tick-价差与半-tick-中点" aria-label="Permalink to &quot;奇数 tick 价差与半 tick 中点&quot;">​</a></h3><p>\\(s=a-b=n\\Delta\\)。\\(n\\) 为奇数时，\\(m\\) 不是 tick 的整数倍。报价规则用 \\(P\\gt m\\) 判买，此时 \\(P\\) 仍在格子上，\\(m\\) 不在。这合法。不合法的是回测里把限价设成 \\(m\\) 再假设它会显示在公开簿上。peg-mid 指令由交易所或经纪商托管，撮合时按当时中点成交，但该中点随 BBO 移动，且常有保护限价（limit of peg）仍须落在格子上。写订单状态机时，peg 的「价格」是规则，不是一个固定的 \\(n\\Delta\\)。</p><p><span class="marginnote">亚 tick 改善常见于零售内化和部分 ATS：成交价可以是 \\(b+0.001\\) 这类不在公开 tick 上的点。打印会出现在公开 BBO 内部。这不是数据错误，是公开栅格与允许的成交栅格不一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合成簿时保存两套价格：交易所可显示的 tick 栅格，以及成交实际发生的价格（可含亚 tick、中点）。有效价差对照公开中点；若要评价零售改善，另报相对公开 BBO 的改善金额。下单模块把目标价投影到合法 tick：买向 \\(b\\) 方向取整还是向更积极方向取整，必须按订单类型写死，不能四舍五入——四舍五入会把买单投影到更贵的 tick。数量投影到手数，剩余零股走允许零股的通道或放弃。</p><p>微观价格（depth-weighted mid）是分析对象，用于比 BBO 中点更稳的标记；它通常也不在格子上。用微观价格当限价，同样不可提交。研究与交易的接口应是：信号可以在连续空间，指令必须在栅格。Hasbrouck 的经验中点处理不自动授权你把中点当成可挂价格。</p><h3 id="栅格投影如何进入回测" tabindex="-1">栅格投影如何进入回测 <a class="header-anchor" href="#栅格投影如何进入回测" aria-label="Permalink to &quot;栅格投影如何进入回测&quot;">​</a></h3><p>连续权重 \\(w\\) 变成股数 \\(q=wV/P\\) 再变成 \\(q&#39;=\\mathrm{round}(q/\\mathrm{lot})\\times\\mathrm{lot}\\)。小资金、高价股、细持仓上，投影会把许多名字的目标头寸打成零，组合实际暴露比信号少一块。这应计入容量，而不是在年化收益里假装成交了小数股。价格投影在 \\(n=1\\) 的股票上尤其痛：想改善半个 tick 做不成，只能吃对方或排队。回测若允许任意实数限价，夏普来自不可提交的价格。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公开栅格协调竞争：所有人在同一组点上排队，时间优先有定义。格子内匹配破坏这一协调，换来价格改善和隐藏。对价差分解：展示层的 \\(s\\) 仍是 \\(n\\Delta\\)；经济层的有效价差可以小于 \\(s\\)，因为成交发生在格子内部。先修课费用可以把名义价差压到一 tick；本课说明即使一 tick，内部匹配仍能再削有效价差。两者叠加，公开 BBO 作为成本代理越来越弱。</p><p>对信息：格子内成交若不立即影响公开报价，价格发现会延迟写到展示层。Hasbrouck 信息份额需要多市场报价；若大量成交在中点完成且不更新 BBO，份额会偏向仍在格子上报价的场所。这是后课碎片化的伏笔。</p><p><span class="marginnote">不要把 <a href="/quant/kyle-model">Kyle</a> 的连续价格 \\(p=\\mu+\\lambda y\\) 直接当成可提交价。均衡价格几乎必然落在 tick 之间；真实成交是栅格上的投影加内部匹配。校准 lambda 用的是成交价或中点变化，不是「模型价可下单」。</span></p>',18)),(t(),c(d,null,{default:i(()=>[p(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22tick%20%CE%94%22%5D%20--%3E%20G%5B%22%E5%85%AC%E5%BC%80%E4%BB%B7%E6%A0%BC-%E6%95%B0%E9%87%8F%E6%A0%85%E6%A0%BC%22%5D%0A%20%20L%5B%22%E6%89%8B%E6%95%B0%20lot%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20Q%5B%22%E5%8F%AF%E6%98%BE%E7%A4%BA%E9%99%90%E4%BB%B7%22%5D%0A%20%20M%5B%22%E4%B8%AD%E7%82%B9%20%2F%20%E4%BA%9A%20tick%22%5D%20--%3E%20I%5B%22%E6%A0%BC%E5%AD%90%E5%86%85%E5%8C%B9%E9%85%8D%22%5D%0A%20%20Q%20--%3E%20BBO%5B%22%E5%B1%95%E7%A4%BA%20BBO%22%5D%0A%20%20I%20--%3E%20P%5B%22%E6%89%93%E5%8D%B0%E4%BB%B7%E5%8F%AF%E5%9C%A8%20BBO%20%E5%86%85%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="peg-的价格是规则不是格子点" tabindex="-1">peg 的价格是规则不是格子点 <a class="header-anchor" href="#peg-的价格是规则不是格子点" aria-label="Permalink to &quot;peg 的价格是规则不是格子点&quot;">​</a></h3><p>peg-mid 随 BBO 移动，限价保护仍须落在 tick 上。状态机若把 peg 存成一个固定的 \\(n\\Delta\\)，撤改会用错参照。格子内匹配的订单，主键是规则标识，不是价格坐标。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不同资产的栅格定义不同。期货是最小跳动与合约乘数；期权是行权价网格加权利金 tick，远比股票粗；债券 OTC 常常是收益率网格或「价格的 1/32」，见公司债课。不要用股票 \\(\\Delta\\) 去取整债券报价。加密交易所 tick 极细，栅格约束弱，费用和 lot 成为实际栅格。</p><p><span class="marginnote">回测允许任意实数限价时，夏普有一部分来自不可提交的半 tick。投影规则必须进撮合器，而不能只在下单前四舍五入一次。</span></p><p>本课不写如何选择 peg 参数去抢中点流动性。下一课进入暗池与 ATS 的中点协议，那是格子内匹配的场所形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公开可提交坐标是 \\((n\\Delta, k\\cdot\\mathrm{lot})\\)；中点经常落在格子外。</li><li>有效价差可以小于报价价差，因为成交允许在栅格内部发生。</li><li>信号的连续价格必须投影到 tick；四舍五入会改变买卖方向的进取程度。</li><li>仓位投影到手数会切断小权重，属于容量而不是 alpha。</li><li>微观价格是分析标记，不是限价。</li><li>出处：Harris, <em>Trading and Exchanges</em>；Hasbrouck 对中点与微观价格的经验处理；交易所对 peg / midpoint 指令的公开规格。</li></ul>',8))])}const A=l(h,[["render",m]]);export{g as __pageData,A as default};
